export type ParsedDepositRevenueInstruction<
  TProgram extends string = typeof AXEL_V2_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Supplies the revenue and pays for the period record. */
    operator: TAccountMetas[0];
    /** Must equal `project.oracle`. */
    oracle: TAccountMetas[1];
    config: TAccountMetas[2];
    project: TAccountMetas[3];
    period: TAccountMetas[4];
    paymentMint: TAccountMetas[5];
    operatorPaymentAccount: TAccountMetas[6];
    revenueVault: TAccountMetas[7];
    treasury: TAccountMetas[8];
    treasuryTokenAccount: TAccountMetas[9];
    paymentTokenProgram: TAccountMetas[10];
    associatedTokenProgram: TAccountMetas[11];
    systemProgram: TAccountMetas[12];
  };
  data: DepositRevenueInstructionData;
};

export function parseDepositRevenueInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositRevenueInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      operator: getNextAccount(),
      oracle: getNextAccount(),
      config: getNextAccount(),
      project: getNextAccount(),
      period: getNextAccount(),
      paymentMint: getNextAccount(),
      operatorPaymentAccount: getNextAccount(),
      revenueVault: getNextAccount(),
      treasury: getNextAccount(),
      treasuryTokenAccount: getNextAccount(),
      paymentTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDepositRevenueInstructionDataDecoder().decode(instruction.data),
  };
}
